            $fileIdentity = $this->dataFileIdentity;
            $path = $this->physicalDataPath;
            $readerLease = new OmaPlugCtlPluginDataIndexedJsonlStoreReaderLease($path . '.readers.lock');
            return new OmaPlugCtlPluginDataIndexedJsonlStoreCursor(
                $this->indexRoots[$index] ?? null, $lower, $upper, $direction,
                fn (array $entry): OmaPlugCtlPluginData => new OmaPlugCtlPluginData($this->ReadRecord($entry, $fileIdentity, $path)),
                self::MEASURE_DURATIONS, $readerLease
            );
        });
    }

    /** Save derived lookup state. Fresh instances restore it and replay only the later tail. */
    public function checkpoint(bool $dryRun = false): array
    {
        return $this->WithLock('checkpoint', function () use ($dryRun): array {
            if (!$dryRun) { $this->EnsureEmptyFiles(); $this->WriteCheckpoint(); }
            return [
                'dry_run' => $dryRun, 'data_path' => $this->dataPath,
                'checkpoint_path' => $this->physicalDataPath . '.checkpoint.json',
                'current_record_count' => count($this->currentRecords),
                'retained_operation_count' => count($this->completedOperations),
                'data_position_bytes' => $this->dataPositionBytes,
            ];
        }, true);
    }

    /** Rewrite current rows and keys, retaining retry receipts and open cursor generations. */
    public function pack(bool $dryRun = false): array
    {
        return $this->WithLock('pack', function () use ($dryRun): array {
            $result = [
                'dry_run' => $dryRun, 'data_path' => $this->dataPath,
                'current_record_count' => count($this->currentRecords),
                'retained_operation_count' => count($this->completedOperations),
                'previous_data_bytes' => $this->dataPositionBytes,
                'previous_index_bytes' => $this->indexPositionBytes,
            ];
            if ($dryRun) { return $result; }
            $this->EnsureEmptyFiles();
            $directory = $this->dataPath . '.generations';
            $this->EnsureDirectory($directory);
            $identifier = bin2hex(random_bytes(16));
            $path = $directory . '/' . $identifier . '.jsonl';
            $data = $this->Open($path, 'x+b');
            $previousChecksum = null;
            try {
                foreach ($this->currentRecords as $entry) {
                    $record = $this->ReadRecord($entry);
                    $receipt = $this->completedOperations[$entry['record_version_identifier']];
                    $commit = [
                        'schema_identifier' => self::SCHEMA_IDENTIFIER,
                        'previous_commit_checksum' => $previousChecksum,
                        'operation' => 'snapshot',
                        'record_version_identifier' => $entry['record_version_identifier'],
                        'replaces_record_version_identifier' => $receipt['result']['replaces_record_version_identifier'],
                        'request_checksum' => $receipt['request_checksum'],
                        'key' => $this->SelectFields($record, self::KEY_FIELDS),
                        'record' => $record,
                    ];
                    $this->WriteAll($data, self::Frame($commit));
                    $previousChecksum = hash('sha256', self::Encode($commit));
                }
                $this->Sync($data);
                $status = fstat($data);
            } finally { fclose($data); }
            $recovery = self::Frame([
                'format_version' => 1, 'schema_identifier' => self::SCHEMA_IDENTIFIER,
                'generation_identifier' => $identifier, 'completed_operations' => $this->completedOperations,
            ]);
            $this->AtomicWrite($path . '.recovery.json', $recovery);
            $manifest = [
                'format_version' => 1, 'schema_identifier' => self::SCHEMA_IDENTIFIER,
                'generation_identifier' => $identifier,
                'baseline_record_count' => count($this->currentRecords),
                'baseline_data_bytes' => $status['size'],
                'baseline_commit_checksum' => $previousChecksum,
                'recovery_checksum' => hash('sha256', $recovery),
            ];
            // Build the entire unpublished generation before changing the shared pointer.
            $candidate = new self($this->dataPath);
            $candidate->physicalDataPath = $path;
            $candidate->generationIdentifier = $identifier;
            $candidate->generationManifest = $manifest;
            $candidate->buildingGeneration = true;
            $candidate->Synchronize(true);
            $candidate->WriteCheckpoint();
            $this->AtomicWrite($this->dataPath . '.current.json', self::Frame($manifest));
            $this->ResolveGeneration();
            $this->Synchronize();
            return $result + [
                'generation_identifier' => $identifier,
                'packed_data_bytes' => $this->dataPositionBytes,
                'packed_index_bytes' => $this->indexPositionBytes,
                'retired_generations_removed' => $this->CleanupGenerations(),
            ];
        }, true);
    }

    public function Find(array $criteria = []): array
    {
        $criteria = $this->NormalizeRecord($criteria);
        return $this->WithLock('Find', function () use ($criteria): array {
            $entries = null;
            if (array_diff(self::KEY_FIELDS, array_keys($criteria)) === []) {
                $entry = $this->currentRecords[$this->Signature($this->SelectFields($criteria, self::KEY_FIELDS))] ?? null;
                $entries = $entry === null ? [] : [$entry];
            }
            if ($entries === null) {
                // Prefer the longest constrained index prefix; unindexed searches scan current keys only.
                $selectedIndex = 'primary';
                $selectedPrefix = [];
                foreach (self::INDEX_GROUPS as $index => $fields) {
                    $prefix = [];
                    foreach ($fields as $field) {
                        if (!array_key_exists($field, $criteria)) { break; }
                        $prefix[] = $criteria[$field];
                    }
                    if (count($prefix) > count($selectedPrefix)) { $selectedIndex = $index; $selectedPrefix = $prefix; }
                }
                $this->EnsureIndex($selectedIndex);
                $entries = OmaPlugCtlPluginDataIndexedJsonlStoreIndexNode::Walk($this->indexRoots[$selectedIndex] ?? null, $selectedPrefix, $selectedPrefix, false);
            }
            $rows = [];
            $readHandle = null;
            try {
                foreach ($entries as $entry) {
                    if ($readHandle === null) {
                        $readHandle = $this->Open($this->physicalDataPath, 'rb');
                        $this->AssertReadHandleIdentity($readHandle, $this->physicalDataPath, $this->dataFileIdentity);
                    }
                    $row = $this->ReadRecord($entry, readHandle: $readHandle, snapshotValidated: true);
                    if ($this->Matches($row, $criteria)) { $rows[] = $row; }
                }
                // Find returns one complete array. Refuse it if the path changed during the read.
                if ($readHandle !== null) { $this->AssertReadHandleIdentity($readHandle, $this->physicalDataPath, $this->dataFileIdentity); }
            } finally { if (is_resource($readHandle)) { fclose($readHandle); } }
            return $rows;
        });
    }

    /** Reuse recordVersionIdentifier when retrying an uncertain write. */
    /**
     * List exact matches in stable file order, with optional sorting and paging.
     */
    public function List(
        array $criteria = [],
        ?string $orderBy = null,
        string $direction = 'asc',
        ?int $limit = null,
        int $offset = 0
    ): array {
        return $this->SortAndPage(
            $this->Find($criteria),
            $orderBy,
            $direction,
            $limit,
            $offset
        );
    }

    /**
     * Search scalar field values case-insensitively after applying exact criteria.
     */
    public function Search(
        string $query,
        array $fields = [],
        array $criteria = [],
        ?string $orderBy = null,
        string $direction = 'asc',
        ?int $limit = null,
        int $offset = 0
    ): array {
        $query = trim($query);
        if ($query === '') {
            throw new InvalidArgumentException('Search query may not be empty.');
        }
        if ($fields === []) {
            $fields = self::FIELDS;
        }
        $uniqueFields = [];
        foreach ($fields as $field) {
            if (!is_string($field) || !in_array($field, self::FIELDS, true)) {
                throw new InvalidArgumentException('Unknown search field: ' . (string) $field);
            }
            $uniqueFields[$field] = true;
        }
        $fields = array_keys($uniqueFields);

        $matches = [];
        foreach ($this->Find($criteria) as $row) {
            foreach ($fields as $field) {
                $value = $row[$field];
                if ($value !== null && stripos((string) $value, $query) !== false) {
                    $matches[] = $row;
                    break;
                }
            }
        }
        return $this->SortAndPage(
            $matches,
            $orderBy,
            $direction,
            $limit,
            $offset
        );
    }

    /**
     * Resolve several unique records with one persistence read.
     *
     * Each selector may use any modeled fields. Rows preserve selector order;
     * missing selectors are returned separately. A selector matching more than
     * one row is rejected so callers cannot silently consume ambiguous data.
     */
    public function FindMany(array $criteriaSets, bool $requireAll = false): array
    {
        $selectors = [];
        $seen = [];
        foreach ($criteriaSets as $index => $criteria) {
            if (!is_array($criteria) || $criteria === []) {
                throw new InvalidArgumentException(
                    'FindMany selector ' . ($index + 1) . ' must be a non-empty field map.'
                );
            }
            $this->AssertKnownFields($criteria);
            $criteria = $this->NormalizeValues($criteria);
            $signatureValues = $criteria;
            ksort($signatureValues);
            $signature = json_encode(
                $signatureValues,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR
            );
            if (isset($seen[$signature])) {
                throw new InvalidArgumentException(
                    'FindMany contains a duplicate selector at position ' . ($index + 1) . '.'
                );
            }
            $seen[$signature] = true;
            $selectors[] = $criteria;
        }
        if ($selectors === []) {
            return ['rows' => [], 'missing' => []];
        }

        // Find() crosses the persistence boundary exactly once.
        $availableRows = $this->Find();
        $rows = [];
        $missing = [];
        foreach ($selectors as $index => $criteria) {
            $matched = [];
            foreach ($availableRows as $row) {
                if ($this->RecordMatches($row, $criteria)) {
                    $matched[] = $row;
                }
            }
            if (count($matched) > 1) {
                throw new RuntimeException(
                    'FindMany selector ' . ($index + 1)
                    . ' is ambiguous; found ' . count($matched) . ' records.'
                );
            }
            if ($matched === []) {
                $missing[] = $criteria;
                continue;
            }
            $rows[] = $matched[0];
        }
        if ($requireAll && $missing !== []) {
            throw new RuntimeException(
                'FindMany requires every selector; missing ' . count($missing) . ' record(s).'
            );
        }
        return ['rows' => $rows, 'missing' => $missing];
    }
    public function Insert($record, bool $dryRun = false, ?string $recordVersionIdentifier = null): array
    {
        $values = $this->NormalizeRecord($record);
        $this->AssertCompleteRecord($values);
        return $this->Mutate('insert', $this->SelectFields($values, self::KEY_FIELDS), $values, $dryRun, $recordVersionIdentifier, null);
    }

    public function Update(
        array $key, $record, bool $dryRun = false,
        ?string $recordVersionIdentifier = null, ?string $expectedRecordVersionIdentifier = null
    ): array {
        $key = $this->NormalizeKey($key);
        $values = $this->NormalizeRecord($record);
        foreach (self::KEY_FIELDS as $field) {
            if (array_key_exists($field, $values) && $values[$field] !== $key[$field]) {
                throw new InvalidArgumentException('Update cannot change a primary key.');
            }
            unset($values[$field]);
        }
        if ($values === []) { throw new InvalidArgumentException('Update requires at least one non-key field.'); }
        return $this->Mutate('update', $key, $values, $dryRun, $recordVersionIdentifier, $expectedRecordVersionIdentifier);
    }

    public function Delete(
        array $key, bool $dryRun = false,
        ?string $recordVersionIdentifier = null, ?string $expectedRecordVersionIdentifier = null
    ): array {
        return $this->Mutate('delete', $this->NormalizeKey($key), [], $dryRun, $recordVersionIdentifier, $expectedRecordVersionIdentifier);
    }

    private function Mutate(string $operation, array $key, array $values, bool $dryRun, ?string $identifier, ?string $expected): array
    {
        $identifier ??= bin2hex(random_bytes(16));
        if (!preg_match('/^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/D', $identifier)) {
            throw new InvalidArgumentException('Record version identifier must contain 1–128 letters, digits, dots, underscores, colons or hyphens.');
        }
        $requestChecksum = hash('sha256', self::Encode([$operation, $key, $values, $expected]));
        return $this->WithLock(ucfirst($operation), function () use ($operation, $key, $values, $dryRun, $identifier, $expected, $requestChecksum): array {
            $signature = $this->Signature($key);
            if (isset($this->completedOperations[$identifier])) {
                $completed = $this->completedOperations[$identifier];
                if ($completed['request_checksum'] !== $requestChecksum) {
                    throw new RuntimeException('Record version identifier was already used for a different request.');
                }
                if (!$dryRun) { $this->RefreshWatchAfterCommit($signature, $operation, $completed['result']); }
                return $completed['result'] + ['replayed' => true];
            }
            $current = $this->currentRecords[$signature] ?? null;
            $this->AssertRecordAvailable($signature);
            if (($operation === 'insert') !== ($current === null)) {
                throw new RuntimeException($operation . ' requires ' . ($operation === 'insert' ? 'an unused' : 'an existing') . ' primary key.');
            }
            $watchedVersion = $operation === 'insert' ? null : ($this->watchedRecordVersions[$signature] ?? null);
            if ($watchedVersion !== null && $expected !== null && $expected !== $watchedVersion) {
                throw new RuntimeException('Expected version differs from the watch; refresh or clear the watch first.');
            }
            // Keep the automatic guard outside the request checksum so retry IDs remain
            // stable when a successful write advances this instance's watched version.
            $expected ??= $watchedVersion;
            if ($expected !== null && ($current['record_version_identifier'] ?? null) !== $expected) {
                throw new RuntimeException('Predecessor version conflict.');
            }
            $record = match ($operation) {
                'insert' => $values,
                'update' => array_replace($this->ReadRecord($current), $values),
                default => null,
            };
            if ($record !== null) { $this->AssertUnique($record, $this->Signature($key)); }
            $commit = [
                'schema_identifier' => self::SCHEMA_IDENTIFIER,
                'previous_commit_checksum' => $this->previousCommitChecksum,
                'operation' => $operation,
                'record_version_identifier' => $identifier,
                'replaces_record_version_identifier' => $current['record_version_identifier'] ?? null,
                'request_checksum' => $requestChecksum,
                'key' => $key,
                'record' => $record,
            ];
            if ($dryRun) { return ['dry_run' => true, 'data_path' => $this->dataPath] + $commit; }
            $handle = $this->Open($this->physicalDataPath, 'ab');
            try { $this->WriteAll($handle, self::Frame($commit)); $this->Sync($handle); }
            finally { fclose($handle); }
            // Commit is durable before index publication. Replay repairs any unpublished delta.
            $this->Synchronize(true);
            $this->RefreshWatchAfterCommit($signature, $operation, $this->completedOperations[$identifier]['result']);
            return $this->completedOperations[$identifier]['result'] + ['replayed' => false];
        }, true);
    }

    private function RefreshWatchAfterCommit(string $signature, string $operation, array $result): void
    {
        if (!isset($this->watchedRecordVersions[$signature])
            || $this->watchedRecordVersions[$signature] !== $result['replaces_record_version_identifier']) { return; }
        $currentVersion = $this->currentRecords[$signature]['record_version_identifier'] ?? null;
        if ($operation === 'delete' && $currentVersion === null) {
            unset($this->watchedRecordVersions[$signature]);
        } elseif ($currentVersion === $result['record_version_identifier']) {
            $this->watchedRecordVersions[$signature] = $currentVersion;
        }
        // Replaying an older receipt must never adopt a later writer's version.
    }

    private function WithLock(string $operation, callable $callback, bool $writing = false, int $waitMilliseconds = 5000): mixed
    {
        if ($this->requiresReopen) { throw new RuntimeException('Store requires operator recovery and a new instance.'); }
        $operationStartedAtNanoseconds = self::MEASURE_DURATIONS ? hrtime(true) : null;
        $this->checkpointLoaded = false;
        $this->replayedRecordCount = 0;
        $lock = $this->Open($this->dataPath . '.lock', 'c+b');
        try {
            $this->AcquireLock($lock, $writing ? LOCK_EX : LOCK_SH, $waitMilliseconds);
            $this->ResolveGeneration();
            $this->deferCheckpointIndexes = $operation === 'Find';
            try { $this->Synchronize(false, $writing); }
            catch (OmaPlugCtlPluginDataIndexedJsonlStoreRecoveryRequired $recovery) {
                // Release before upgrading: two simultaneous repairing readers must not deadlock.
                flock($lock, LOCK_UN);
                $this->AcquireLock($lock, LOCK_EX, $waitMilliseconds);
                $this->ResolveGeneration();
                $this->Synchronize();
            }
            if ($operation !== 'Find') {
                foreach (array_keys($this->deferredIndexes) as $index) { $this->EnsureIndex($index); }
            }
            return $callback();
        } catch (Throwable $error) {
            $this->ResetCache();
            throw $error;
        } finally {
            $this->deferCheckpointIndexes = false;
            flock($lock, LOCK_UN);
            fclose($lock);
            if ($operationStartedAtNanoseconds !== null) {
                $this->lastOperationMetrics = [
                    'operation' => $operation,
                    'operation_duration_milliseconds' => (hrtime(true) - $operationStartedAtNanoseconds) / 1000000,
                    'checkpoint_loaded' => $this->checkpointLoaded,
                    'replayed_record_count' => $this->replayedRecordCount,
                ];
            }
        }
    }

    private function ResetCache(): void
    {
        $this->currentRecords = $this->completedOperations = $this->indexRoots = $this->uniqueKeys = $this->deferredIndexes = [];
        $this->dataPositionBytes = $this->indexPositionBytes = 0;
        $this->previousCommitChecksum = $this->dataFileIdentity = $this->indexFileIdentity = null;
        $this->lastDataFrame = $this->lastIndexFrame = null;
        $this->generationInitialized = $this->checkpointAttempted = false;
        $this->baselineRecordsRemaining = 0;
    }

    private function ResolveGeneration(): void
    {
        $manifestPath = $this->dataPath . '.current.json';
        clearstatcache(true, $manifestPath);
        if (!is_file($manifestPath)) {
            if ($this->generationIdentifier !== 'original'
                || (!is_file($this->dataPath) && (glob($this->dataPath . '.generations/*.jsonl') ?: []) !== [])) {
                throw new RuntimeException('Published generation manifest is missing.');
            }
            return;
        }
        $manifest = self::DecodeFrame($this->ReadFile($manifestPath));
        if (($manifest['format_version'] ?? null) !== 1 || ($manifest['schema_identifier'] ?? null) !== self::SCHEMA_IDENTIFIER
            || !is_string($manifest['generation_identifier'] ?? null) || !preg_match('/^[a-f0-9]{32}$/D', $manifest['generation_identifier'])
            || !is_int($manifest['baseline_record_count'] ?? null) || $manifest['baseline_record_count'] < 0
            || !is_int($manifest['baseline_data_bytes'] ?? null) || $manifest['baseline_data_bytes'] < 0
            || !array_key_exists('baseline_commit_checksum', $manifest)
            || ($manifest['baseline_record_count'] === 0
                ? ($manifest['baseline_commit_checksum'] !== null || $manifest['baseline_data_bytes'] !== 0)
                : (!is_string($manifest['baseline_commit_checksum']) || !preg_match('/^[a-f0-9]{64}$/D', $manifest['baseline_commit_checksum'])))
            || !is_string($manifest['recovery_checksum'] ?? null) || !preg_match('/^[a-f0-9]{64}$/D', $manifest['recovery_checksum'])) {
            throw new RuntimeException('Invalid generation manifest.');
        }
        if ($manifest['generation_identifier'] === $this->generationIdentifier) {
            if ($manifest !== $this->generationManifest) { throw new RuntimeException('Published generation manifest was changed.'); }
            return;
        }
        $directory = $this->dataPath . '.generations';
        if (is_link($directory)) { throw new RuntimeException('Generation directory symlinks are not supported.'); }
        $this->generationIdentifier = $manifest['generation_identifier'];
        $this->generationManifest = $manifest;
        $this->physicalDataPath = $directory . '/' . $this->generationIdentifier . '.jsonl';
        $this->ResetCache();
    }

    private function InitializeGeneration(): void
    {
        if ($this->generationInitialized) { return; }
        if ($this->generationManifest !== null) {
            $contents = $this->ReadFile($this->physicalDataPath . '.recovery.json');
            if (!hash_equals($this->generationManifest['recovery_checksum'], hash('sha256', $contents))) {
                throw new RuntimeException('Packed recovery receipts are missing or corrupt.');
            }
            $recovery = self::DecodeFrame($contents);
            if (($recovery['format_version'] ?? null) !== 1 || ($recovery['schema_identifier'] ?? null) !== self::SCHEMA_IDENTIFIER
                || ($recovery['generation_identifier'] ?? null) !== $this->generationIdentifier) {
                throw new RuntimeException('Packed recovery receipts belong to a different generation.');
            }
            $this->completedOperations = $this->ValidateReceipts($recovery['completed_operations'] ?? null);
            $this->baselineRecordsRemaining = $this->generationManifest['baseline_record_count'];
        }
        $this->generationInitialized = true;
    }

    private function ValidateReceipts(mixed $receipts): array
    {
        if (!is_array($receipts)) { throw new RuntimeException('Invalid retained operation receipts.'); }
        foreach ($receipts as $identifier => &$receipt) {
            if (!preg_match('/^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/D', (string) $identifier)
                || !is_array($receipt) || !is_string($receipt['request_checksum'] ?? null)
                || !preg_match('/^[a-f0-9]{64}$/D', $receipt['request_checksum'])
                || !is_array($receipt['result'] ?? null) || ($receipt['result']['affected_rows'] ?? null) !== 1
                || ($receipt['result']['record_version_identifier'] ?? null) !== (string) $identifier
                || !array_key_exists('replaces_record_version_identifier', $receipt['result'])
                || ($receipt['result']['replaces_record_version_identifier'] !== null
                    && !is_string($receipt['result']['replaces_record_version_identifier']))) {
                throw new RuntimeException('Invalid retained operation receipt.');
            }
            $receipt['result']['data_path'] = $this->dataPath;
        }
        unset($receipt);
        return $receipts;
    }

    private function EnsureEmptyFiles(): void
    {
        foreach ([$this->physicalDataPath, $this->physicalDataPath . '.indexes.jsonl'] as $path) {
            if (!is_file($path)) {
                $handle = $this->Open($path, 'x+b');
                try { $this->Sync($handle); } finally { fclose($handle); }
            }
        }
        $this->Synchronize();
    }

    private function WriteCheckpoint(): void
    {
        $orderedSignatures = [];
        foreach (self::INDEX_GROUPS as $index => $fields) {
            $orderedSignatures[$index] = [];
            foreach (OmaPlugCtlPluginDataIndexedJsonlStoreIndexNode::Walk($this->indexRoots[$index] ?? null, [], [], false) as $entry) {
                $orderedSignatures[$index][] = $entry['sort_values'][count($fields)];
            }
        }
        $this->AtomicWrite($this->physicalDataPath . '.checkpoint.json', self::Frame([
            'format_version' => 1, 'schema_identifier' => self::SCHEMA_IDENTIFIER,
            'generation_identifier' => $this->generationIdentifier,
            'data_file_identity' => $this->dataFileIdentity, 'index_file_identity' => $this->indexFileIdentity,
            'data_position_bytes' => $this->dataPositionBytes, 'index_position_bytes' => $this->indexPositionBytes,
            'previous_commit_checksum' => $this->previousCommitChecksum,
            'last_data_frame' => $this->lastDataFrame, 'last_index_frame' => $this->lastIndexFrame,
            'current_records' => $this->currentRecords, 'completed_operations' => $this->completedOperations,
            'ordered_primary_key_signatures' => $orderedSignatures,
        ]));
    }

    private function RestoreCheckpoint($data, $indexes): void
    {
        $path = $this->physicalDataPath . '.checkpoint.json';
        if (!is_file($path)) { return; }
        try {
            $saved = self::DecodeFrame($this->ReadFile($path));
            if (($saved['format_version'] ?? null) !== 1 || ($saved['schema_identifier'] ?? null) !== self::SCHEMA_IDENTIFIER
                || ($saved['generation_identifier'] ?? null) !== $this->generationIdentifier
                || ($saved['data_file_identity'] ?? null) !== $this->dataFileIdentity
                || !is_int($saved['data_position_bytes'] ?? null) || $saved['data_position_bytes'] < 0
                || !is_int($saved['index_position_bytes'] ?? null) || $saved['index_position_bytes'] < 0) { return; }
            if (fstat($data)['size'] < $saved['data_position_bytes']) {
                $this->requiresReopen = true;
                throw new RuntimeException('Checkpoint proves committed data was truncated.');
            }
            if (($saved['index_file_identity'] ?? null) !== $this->indexFileIdentity
                || fstat($indexes)['size'] < $saved['index_position_bytes']
                || $saved['data_position_bytes'] < ($this->generationManifest['baseline_data_bytes'] ?? 0)
                || !$this->ValidAnchor($data, $saved['last_data_frame'] ?? null, $saved['data_position_bytes'])
                || !$this->ValidAnchor($indexes, $saved['last_index_frame'] ?? null, $saved['index_position_bytes'])) { return; }
            if ($saved['data_position_bytes'] === 0) {
                if (($saved['previous_commit_checksum'] ?? null) !== null || $saved['index_position_bytes'] !== 0) { return; }
            } elseif (!is_string($saved['previous_commit_checksum'] ?? null)
                || !preg_match('/^[a-f0-9]{64}$/D', $saved['previous_commit_checksum'])) { return; }
            $receipts = $this->ValidateReceipts($saved['completed_operations'] ?? null);
            foreach ($this->completedOperations as $identifier => $receipt) {
                if (($receipts[$identifier] ?? null) !== $receipt) { return; }
            }
            $records = $saved['current_records'] ?? null;
            if (!is_array($records)) { return; }
            $roots = $uniqueKeys = $deferred = [];
            foreach ($records as $signature => $entry) {
                if (!is_array($entry) || !is_int($entry['data_offset_bytes'] ?? null) || $entry['data_offset_bytes'] < 0
                    || !is_int($entry['data_length_bytes'] ?? null) || $entry['data_length_bytes'] <= 0
                    || $entry['data_offset_bytes'] + $entry['data_length_bytes'] > $saved['data_position_bytes']
                    || !is_string($entry['data_checksum'] ?? null) || !preg_match('/^[a-f0-9]{64}$/D', $entry['data_checksum'])
                    || !is_string($entry['record_version_identifier'] ?? null) || !isset($receipts[$entry['record_version_identifier']])
                    || !is_array($entry['index_keys'] ?? null) || array_keys($entry['index_keys']) !== array_keys(self::INDEX_GROUPS)) { return; }
                $indexedValues = [];
                foreach (self::INDEX_GROUPS as $index => $fields) {
                    $values = $entry['index_keys'][$index];
                    if (!is_array($values) || !array_is_list($values) || count($values) !== count($fields)) { return; }
                    foreach ($fields as $position => $field) {
                        if (array_key_exists($field, $indexedValues) && $indexedValues[$field] !== $values[$position]) { return; }
                        $indexedValues[$field] = $values[$position];
                    }
                }
                $normalized = $this->NormalizeRecord($indexedValues);
                foreach ($indexedValues as $field => $value) { if ($normalized[$field] !== $value) { return; } }
                if ($this->Signature($this->SelectFields($normalized, self::KEY_FIELDS)) !== $signature) { return; }
                foreach (self::UNIQUE_KEY_GROUPS as $fields) {
                    $index = 'fields:' . implode(',', $fields);
                    $key = self::Encode($entry['index_keys'][$index]);
                    if (isset($uniqueKeys[$index][$key])) { return; }
                    $uniqueKeys[$index][$key] = $signature;
                }
            }
            $orderedSignatures = $saved['ordered_primary_key_signatures'] ?? null;
            if (!is_array($orderedSignatures) || array_keys($orderedSignatures) !== array_keys(self::INDEX_GROUPS)) { return; }
            foreach ($orderedSignatures as $index => $signatures) {
                if (!is_array($signatures) || !array_is_list($signatures) || count($signatures) !== count($records)) { return; }
                $seen = [];
                $previousValues = null;
                foreach ($signatures as $signature) {
                    if (!is_string($signature) || !isset($records[$signature]) || isset($seen[$signature])) { return; }
                    $values = array_merge($records[$signature]['index_keys'][$index], [$signature]);
                    if ($previousValues !== null && OmaPlugCtlPluginDataIndexedJsonlStoreIndexNode::ComparePrefix($previousValues, $values) >= 0) { return; }
                    $previousValues = $values;
                    $seen[$signature] = true;
                }
                // Checkpoints already contain sorted keys: construct balanced trees in linear time.
                if ($this->deferCheckpointIndexes) { $deferred[$index] = $signatures; }
                else { $roots[$index] = OmaPlugCtlPluginDataIndexedJsonlStoreIndexNode::FromOrderedSignatures($signatures, $records, $index, 0, count($signatures)); }
            }
            $this->completedOperations = $receipts;
            $this->currentRecords = $records;
            $this->indexRoots = $roots;
            $this->deferredIndexes = $deferred;
            $this->uniqueKeys = $uniqueKeys;
            $this->dataPositionBytes = $saved['data_position_bytes'];
            $this->indexPositionBytes = $saved['index_position_bytes'];
            $this->previousCommitChecksum = $saved['previous_commit_checksum'];
            $this->lastDataFrame = $saved['last_data_frame'];
            $this->lastIndexFrame = $saved['last_index_frame'];
            $this->baselineRecordsRemaining = 0;
            $this->checkpointLoaded = true;
        } catch (Throwable $error) {
            if ($this->requiresReopen) { throw $error; }
            // Checkpoints are derived: malformed/stale snapshots fall back to committed replay.
        }
    }

    private function ValidAnchor($handle, mixed $anchor, int $position): bool
    {
        if ($position === 0) { return $anchor === null; }
        if (!is_array($anchor) || !is_int($anchor['offset_bytes'] ?? null) || $anchor['offset_bytes'] < 0
            || !is_int($anchor['length_bytes'] ?? null) || $anchor['length_bytes'] <= 0
            || $anchor['offset_bytes'] + $anchor['length_bytes'] !== $position
            || !is_string($anchor['checksum'] ?? null)) { return false; }
        $this->Seek($handle, $anchor['offset_bytes']);
        $contents = stream_get_contents($handle, $anchor['length_bytes']);
        return is_string($contents) && strlen($contents) === $anchor['length_bytes']
            && hash_equals($anchor['checksum'], hash('sha256', $contents));
    }

    /** The exclusive store lock prevents any new cursor from leasing retired generations. */
    private function CleanupGenerations(): int
    {
        $removed = 0;
        $generations = array_filter(glob($this->dataPath . '.generations/*.jsonl') ?: [],
            static fn (string $path): bool => preg_match('/^[a-f0-9]{32}\.jsonl$/D', basename($path)) === 1);
        $paths = array_merge([$this->dataPath], $generations);
        foreach ($paths as $path) {
            if ($path === $this->physicalDataPath || !is_file($path)) { continue; }
            $leasePath = $path . '.readers.lock';
            $lease = $this->Open($leasePath, 'c+b');
            try {
                if (!flock($lease, LOCK_EX | LOCK_NB)) { continue; }
                foreach (['', '.indexes.jsonl', '.checkpoint.json', '.recovery.json'] as $suffix) {
                    if (is_file($path . $suffix) && !unlink($path . $suffix)) { throw new RuntimeException('Unable to remove retired generation.'); }
                }
                if (!unlink($leasePath)) { throw new RuntimeException('Unable to remove retired reader lease.'); }
                $removed++;
            } finally { fclose($lease); }
        }
        return $removed;
    }

    private function Synchronize(bool $dataAlreadySynchronized = false, bool $allowRepair = true): void
    {
        clearstatcache(true, $this->physicalDataPath);
        $indexPath = $this->physicalDataPath . '.indexes.jsonl';
        clearstatcache(true, $indexPath);
        if (!is_file($this->physicalDataPath)) {
            if ($this->generationManifest !== null || $this->dataPositionBytes !== 0
                || is_file($this->physicalDataPath . '.checkpoint.json') || (is_file($indexPath) && filesize($indexPath) !== 0)) {
                $this->requiresReopen = true;
                throw new RuntimeException('Committed data file is missing.');
            }
            return;
        }
        $data = $this->Open($this->physicalDataPath, $allowRepair ? 'r+b' : 'rb');
        $indexes = null;
        try {
            $dataStatus = fstat($data);
            $identity = $dataStatus['dev'] . ':' . $dataStatus['ino'];
            if ($this->generationManifest !== null && $dataStatus['size'] < $this->generationManifest['baseline_data_bytes']) {
                $this->requiresReopen = true;
                throw new RuntimeException('Packed generation data was replaced or truncated.');
            }
            if (($this->dataFileIdentity !== null && $identity !== $this->dataFileIdentity) || $dataStatus['size'] < $this->dataPositionBytes) {
                $this->requiresReopen = true;
                throw new RuntimeException('Committed data was replaced or truncated; reopen only after operator recovery.');
            }
            if (!$allowRepair && !is_file($indexPath)) { throw new OmaPlugCtlPluginDataIndexedJsonlStoreRecoveryRequired(); }
            $indexes = $this->Open($indexPath, $allowRepair ? 'c+b' : 'rb');
            $indexStatus = fstat($indexes);
            $indexIdentity = $indexStatus['dev'] . ':' . $indexStatus['ino'];
            if ($indexStatus['size'] < $this->indexPositionBytes || ($this->indexFileIdentity !== null && $indexIdentity !== $this->indexFileIdentity)) {
                $this->ResetCache();
            }
            $this->dataFileIdentity = $identity;
            $this->indexFileIdentity = $indexIdentity;
            $this->InitializeGeneration();
            if (!$this->checkpointAttempted) {
                $this->checkpointAttempted = true;
                $this->RestoreCheckpoint($data, $indexes);
            }
            $this->Seek($data, $this->dataPositionBytes);
            $this->Seek($indexes, $this->indexPositionBytes);
            $repairedDataTail = false;
            while (($line = fgets($data)) !== false) {
                if (!str_ends_with($line, "\n")) {
                    if ($this->HasPublishedIndexTail($indexes)) { throw new RuntimeException('Published index references incomplete committed data; recover the data file.'); }
                    if (!$allowRepair) { throw new OmaPlugCtlPluginDataIndexedJsonlStoreRecoveryRequired(); }
                    $this->Truncate($data, $this->dataPositionBytes);
                    $repairedDataTail = true;
                    break;
                }
                $commit = self::DecodeFrame($line);
                $this->ValidateCommit($commit);
                $signature = $this->Signature($commit['key']);
                $current = $this->currentRecords[$signature] ?? null;
                $entry = [
                    'data_offset_bytes' => $this->dataPositionBytes,
                    'data_length_bytes' => strlen($line),
                    'record_version_identifier' => $commit['record_version_identifier'],
                    'data_checksum' => hash('sha256', $line),
                    'index_keys' => $commit['record'] === null ? [] : $this->IndexKeys($commit['record']),
                ];
                $delta = [
                    'schema_identifier' => self::SCHEMA_IDENTIFIER,
                    'primary_key_signature' => $signature,
                    'removed_index_keys' => $current['index_keys'] ?? [],
                    'added_index_keys' => $entry['index_keys'],
                    'replaces_record_version_identifier' => $commit['replaces_record_version_identifier'],
                ] + $entry;
                $expectedLine = self::Frame($delta);
                $publishedLine = fgets($indexes);
                if ($publishedLine !== $expectedLine) {
                    if (!$allowRepair) { throw new OmaPlugCtlPluginDataIndexedJsonlStoreRecoveryRequired(); }
                    // Derived index corruption/missing tail is repaired from committed data.
                    if (!$dataAlreadySynchronized) { $this->Sync($data); $dataAlreadySynchronized = true; }
                    if (fstat($indexes)['size'] !== $this->indexPositionBytes) { $this->Truncate($indexes, $this->indexPositionBytes); }
                    else { $this->Seek($indexes, $this->indexPositionBytes); }
                    $this->WriteAll($indexes, $expectedLine);
                    if (!$this->buildingGeneration) { $this->Sync($indexes); }
                }
                $this->ApplyCommit($commit, $signature, $entry, $current);
                $this->lastDataFrame = ['offset_bytes' => $this->dataPositionBytes, 'length_bytes' => strlen($line), 'checksum' => hash('sha256', $line)];
                $this->lastIndexFrame = ['offset_bytes' => $this->indexPositionBytes, 'length_bytes' => strlen($expectedLine), 'checksum' => hash('sha256', $expectedLine)];
                $this->previousCommitChecksum = hash('sha256', self::Encode($commit));
                $this->dataPositionBytes += strlen($line);
                $this->indexPositionBytes += strlen($expectedLine);
                $this->replayedRecordCount++;
                if ($this->baselineRecordsRemaining > 0) {
                    $this->baselineRecordsRemaining--;
                    if ($this->baselineRecordsRemaining === 0 && ($this->dataPositionBytes !== $this->generationManifest['baseline_data_bytes']
                        || $this->previousCommitChecksum !== $this->generationManifest['baseline_commit_checksum'])) {
                        throw new RuntimeException('Packed baseline does not match its manifest.');
                    }
                }
            }
            if (!feof($data) && !$repairedDataTail) { throw new RuntimeException('Unable to finish reading committed data.'); }
            if ($this->baselineRecordsRemaining !== 0) { throw new RuntimeException('Packed baseline is incomplete.'); }
            if (fstat($indexes)['size'] > $this->indexPositionBytes) {
                if ($this->HasPublishedIndexTail($indexes)) { throw new RuntimeException('Published index references missing committed data; recover the data file.'); }
                if (!$allowRepair) { throw new OmaPlugCtlPluginDataIndexedJsonlStoreRecoveryRequired(); }
                $this->Truncate($indexes, $this->indexPositionBytes);
            }
            if ($this->buildingGeneration) { $this->Sync($indexes); }
        } finally {
            fclose($data);
            if (is_resource($indexes)) { fclose($indexes); }
        }
    }

    private function ValidateCommit(array $commit): void
    {
        if (($commit['schema_identifier'] ?? null) !== self::SCHEMA_IDENTIFIER
            || ($commit['previous_commit_checksum'] ?? null) !== $this->previousCommitChecksum
            || !isset($commit['record_version_identifier'], $commit['request_checksum'], $commit['key'], $commit['operation'])
            || !is_string($commit['record_version_identifier']) || !is_string($commit['request_checksum'])
            || !in_array($commit['operation'], ['insert', 'update', 'delete', 'snapshot'], true)
            || !array_key_exists('record', $commit) || !array_key_exists('replaces_record_version_identifier', $commit)) {
            throw new RuntimeException('Invalid commit schema or checksum chain.');
        }
        $key = $this->NormalizeKey($commit['key']);
        $signature = $this->Signature($key);
        $current = $this->currentRecords[$signature] ?? null;
        if ($this->baselineRecordsRemaining > 0) {
            $receipt = $this->completedOperations[$commit['record_version_identifier']] ?? null;
            if ($commit['operation'] !== 'snapshot' || $current !== null || $receipt === null
                || $receipt['request_checksum'] !== $commit['request_checksum']
                || $receipt['result']['replaces_record_version_identifier'] !== $commit['replaces_record_version_identifier']) {
                throw new RuntimeException('Invalid packed baseline receipt.');
            }
        } elseif ($commit['operation'] === 'snapshot' || isset($this->completedOperations[$commit['record_version_identifier']])
            || ($current['record_version_identifier'] ?? null) !== $commit['replaces_record_version_identifier']
            || (($commit['operation'] === 'insert') !== ($current === null))) {
            throw new RuntimeException('Invalid committed predecessor or duplicate version.');
        }
        if ($commit['operation'] === 'delete') {
            if ($commit['record'] !== null) { throw new RuntimeException('Delete commit must contain a tombstone.'); }
        } else {
            $record = $this->NormalizeRecord($commit['record']);
            $this->AssertCompleteRecord($record);
            if ($record !== $commit['record'] || $this->SelectFields($record, self::KEY_FIELDS) !== $key) {
                throw new RuntimeException('Committed record is not canonical or has a different key.');
            }
            $this->AssertUnique($record, $signature);
        }
    }

    private function HasPublishedIndexTail($indexes): bool
    {
        $this->Seek($indexes, $this->indexPositionBytes);
        $line = fgets($indexes);
        $this->Seek($indexes, $this->indexPositionBytes);
        if ($line === false || !str_ends_with($line, "\n")) { return false; }
        try { $entry = self::DecodeFrame($line); }
        catch (JsonException | RuntimeException) { return false; }
        return ($entry['schema_identifier'] ?? null) === self::SCHEMA_IDENTIFIER
            && isset($entry['record_version_identifier'], $entry['data_offset_bytes'], $entry['data_length_bytes']);
    }

    private function ApplyCommit(array $commit, string $signature, array $entry, ?array $current): void
    {
        // A deferred tree is reconstructed from current keys when first needed.
        // Tail replay must invalidate its saved order without publishing a partial tree.
        foreach ($this->deferredIndexes as $index => $_) { $this->deferredIndexes[$index] = null; }
        foreach (($current['index_keys'] ?? []) as $index => $values) {
            if (array_key_exists($index, $this->deferredIndexes)) { continue; }
            $sortValues = array_merge($values, [$signature]);
            $this->indexRoots[$index] = OmaPlugCtlPluginDataIndexedJsonlStoreIndexNode::Remove($this->indexRoots[$index] ?? null, $sortValues);
        }
        foreach (self::UNIQUE_KEY_GROUPS as $fields) {
            $index = 'fields:' . implode(',', $fields);
            if ($current !== null) { unset($this->uniqueKeys[$index][self::Encode($current['index_keys'][$index])]); }
            if ($commit['record'] !== null) { $this->uniqueKeys[$index][self::Encode($entry['index_keys'][$index])] = $signature; }
        }
        if ($commit['record'] === null) { unset($this->currentRecords[$signature]); }
        else {
            $this->currentRecords[$signature] = $entry;
            foreach ($entry['index_keys'] as $index => $values) {
                if (array_key_exists($index, $this->deferredIndexes)) { continue; }
                $indexedEntry = $entry + ['sort_values' => array_merge($values, [$signature])];
                $this->indexRoots[$index] = OmaPlugCtlPluginDataIndexedJsonlStoreIndexNode::Put($this->indexRoots[$index] ?? null, $indexedEntry);
            }
        }
        $this->completedOperations[$commit['record_version_identifier']] = [
            'request_checksum' => $commit['request_checksum'],
            'result' => [
                'affected_rows' => 1, 'data_path' => $this->dataPath,
                'record_version_identifier' => $commit['record_version_identifier'],
                'replaces_record_version_identifier' => $commit['replaces_record_version_identifier'],
            ],
        ];
    }

    private function EnsureIndex(string $index): void
    {
        if (!array_key_exists($index, $this->deferredIndexes)) { return; }
        $signatures = $this->deferredIndexes[$index];
        if ($signatures === null) {
            $signatures = array_keys($this->currentRecords);
            usort($signatures, function (string $a, string $b) use ($index): int {
                return OmaPlugCtlPluginDataIndexedJsonlStoreIndexNode::ComparePrefix(
                    array_merge($this->currentRecords[$a]['index_keys'][$index], [$a]),
                    array_merge($this->currentRecords[$b]['index_keys'][$index], [$b])
                );
            });
        }
        $this->indexRoots[$index] = OmaPlugCtlPluginDataIndexedJsonlStoreIndexNode::FromOrderedSignatures($signatures, $this->currentRecords, $index, 0, count($signatures));
        unset($this->deferredIndexes[$index]);
    }

    private function AssertReadHandleIdentity(mixed $handle, string $path, ?string $identity): void
    {
        clearstatcache(true, $path);
        $current = @lstat($path);
        $opened = fstat($handle);
        if ($current === false || ($current['mode'] & 0170000) !== 0100000
            || $identity !== $current['dev'].':'.$current['ino']
            || $identity !== $opened['dev'].':'.$opened['ino']) {
            throw new RuntimeException('Cursor data file was replaced.');
        }
    }

    private function ReadRecord(array $entry, ?string $fileIdentity = null, ?string $path = null, mixed $readHandle = null, bool $snapshotValidated = false): array
    {
        $path ??= $this->physicalDataPath;
        $handle = $readHandle ?? $this->Open($path, 'rb');
        try {
            if ($readHandle !== null && !$snapshotValidated) {
                $this->AssertReadHandleIdentity($handle, $path, $fileIdentity ?? $this->dataFileIdentity);
            }
            if (!$snapshotValidated) {
                $status = fstat($handle);
                if (($fileIdentity ?? $this->dataFileIdentity) !== $status['dev'] . ':' . $status['ino']) {
                    throw new RuntimeException('Cursor data file was replaced.');
                }
            }
            $this->Seek($handle, $entry['data_offset_bytes']);
            $line = '';
            while (strlen($line) < $entry['data_length_bytes']) {
                $part = fread($handle, $entry['data_length_bytes'] - strlen($line));
                if ($part === false || $part === '') { throw new RuntimeException('Incomplete indexed record.'); }
                $line .= $part;
            }
            if (!hash_equals($entry['data_checksum'], hash('sha256', $line))) { throw new RuntimeException('Indexed record checksum mismatch.'); }
            $commit = self::DecodeFrame($line);
            if ($commit['record_version_identifier'] !== $entry['record_version_identifier'] || !is_array($commit['record'])) {
                throw new RuntimeException('Index points to an invalid record version.');
            }
            return $commit['record'];
        } finally { if ($readHandle === null) { fclose($handle); } }
    }

    private function AssertUnique(array $record, string $signature): void
    {
        foreach (self::UNIQUE_KEY_GROUPS as $fields) {
            $index = 'fields:' . implode(',', $fields);
            $owner = $this->uniqueKeys[$index][self::Encode(array_values($this->SelectFields($record, $fields)))] ?? null;
            if ($owner !== null && $owner !== $signature) { throw new RuntimeException('Alternate unique key collision: ' . implode(',', $fields)); }
        }
    }

    private function IndexKeys(array $record): array
    {
        $keys = [];
        foreach (self::INDEX_GROUPS as $index => $fields) { $keys[$index] = array_values($this->SelectFields($record, $fields)); }
        return $keys;
    }

    private function RecordMatches(array $row, array $criteria): bool
    {
        foreach ($criteria as $field => $expected) {
            if (!array_key_exists($field, $row)) {
                return false;
            }
            $actual = $row[$field];
            if ($actual === null || $expected === null) {
                if ($actual !== $expected) {
                    return false;
                }
            } elseif (self::FIELD_TYPES[$field] === 'numeric') {
                if (!is_numeric($actual)
                    || !is_numeric($expected)
                    || (float) $actual !== (float) $expected) {
                    return false;
                }
            } elseif ((string) $actual !== (string) $expected) {
                return false;
            }
        }
        return true;
    }

    private function SortAndPage(
        array $rows,
        ?string $orderBy,
        string $direction,
        ?int $limit,
        int $offset
    ): array {
        $direction = strtolower($direction);
        if (!in_array($direction, ['asc', 'desc'], true)) {
            throw new InvalidArgumentException('Sort direction must be asc or desc.');
        }
        if ($orderBy !== null && !in_array($orderBy, self::FIELDS, true)) {
            throw new InvalidArgumentException('Unknown order field: ' . $orderBy);
        }
        if ($limit !== null && $limit < 0) {
            throw new InvalidArgumentException('List limit may not be negative.');
        }
        if ($offset < 0) {
            throw new InvalidArgumentException('List offset may not be negative.');
        }

        if ($orderBy !== null) {
            $decorated = [];
            foreach ($rows as $index => $row) {
                $decorated[] = ['index' => $index, 'row' => $row];
            }
            usort(
                $decorated,
                function (array $left, array $right) use ($orderBy, $direction): int {
                    $leftValue = $left['row'][$orderBy];
                    $rightValue = $right['row'][$orderBy];
                    if ($leftValue === $rightValue) {
                        $comparison = 0;
                    } elseif ($leftValue === null) {
                        $comparison = -1;
                    } elseif ($rightValue === null) {
                        $comparison = 1;
                    } elseif (self::FIELD_TYPES[$orderBy] === 'numeric') {
                        $comparison = (float) $leftValue <=> (float) $rightValue;
                    } else {
                        $comparison = strcmp((string) $leftValue, (string) $rightValue);
                    }
                    if ($comparison === 0) {
                        return $left['index'] <=> $right['index'];
                    }
                    return $direction === 'desc' ? -$comparison : $comparison;
                }
            );
            $rows = array_map(
                static fn(array $item): array => $item['row'],
                $decorated
            );
        }

        if ($limit === null) {
            return array_values(array_slice($rows, $offset));
        }
        return array_values(array_slice($rows, $offset, $limit));
    }
    private function NormalizeRecord($record): array
    {
        if (is_object($record) && method_exists($record, 'ToArray')) { $record = $record->ToArray(); }
        if (!is_array($record)) { throw new InvalidArgumentException('Record must be an array or generated model.'); }
        $this->AssertKnownFields($record);
        $normalized = [];
        foreach (self::FIELDS as $field) {
            if (!array_key_exists($field, $record)) { continue; }
            $value = OmaPlugCtlPluginData::NormalizePropertyValue($field, $record[$field]);
            if ($value === null) {
                if (!in_array($field, self::NULLABLE_FIELDS, true)) { throw new InvalidArgumentException('Non-null field: ' . $field); }
            } elseif (self::FIELD_TYPES[$field] === 'numeric') {
                if (!is_numeric($value)) { throw new InvalidArgumentException('Numeric value required: ' . $field); }
                $value += 0;
                if (is_float($value) && !is_finite($value)) { throw new InvalidArgumentException('Finite numeric value required: ' . $field); }
                // Canonical integral floats make numeric aliases use identical index keys.
                if (is_float($value) && $value >= PHP_INT_MIN && $value < PHP_INT_MAX && floor($value) === $value) { $value = (int) $value; }
            } else {
                if (!is_scalar($value)) { throw new InvalidArgumentException('Scalar value required: ' . $field); }
                $value = (string) $value;
            }
            $normalized[$field] = $value;
        }
        return $normalized;
    }

    private function NormalizeValues(array $values): array { return $this->NormalizeRecord($values); }

    private function AssertKnownFields(array $values): void
    {
        if (array_diff(array_keys($values), self::FIELDS) !== []) { throw new InvalidArgumentException('Unknown modeled field.'); }
    }

    private function AssertCompleteRecord(array $values): void
    {
        if (array_diff(self::FIELDS, array_keys($values)) !== []) { throw new InvalidArgumentException('Record is missing modeled fields.'); }
    }

    private function NormalizeKey(array $key): array
    {
        if (count($key) !== count(self::KEY_FIELDS) || array_diff(self::KEY_FIELDS, array_keys($key)) !== []) {
            throw new InvalidArgumentException('Supply exactly the complete primary key.');
        }
        return $this->SelectFields($this->NormalizeRecord($key), self::KEY_FIELDS);
    }

    private function NormalizeBound(array $bound, array $fields): array
    {
        if ($bound === []) { return []; }
        $prefix = array_slice($fields, 0, count($bound));
        if (array_diff(array_keys($bound), $prefix) !== [] || count($prefix) !== count($bound)) {
            throw new InvalidArgumentException('Range bounds must name a leading prefix of index fields.');
        }
        return array_values($this->SelectFields($this->NormalizeRecord($bound), $prefix));
    }

    private function SelectFields(array $values, array $fields): array
    {
        $selected = [];
        foreach ($fields as $field) { $selected[$field] = $values[$field]; }
        return $selected;
    }

    private function Signature(array $key): string { return self::Encode(array_values($key)); }

    private function Matches(array $row, array $criteria): bool
    {
        foreach ($criteria as $field => $value) { if ($row[$field] !== $value) { return false; } }
        return true;
    }

    private static function Encode(mixed $value): string
    {
        return json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
