    public static function ComparePrefix(array $left, array $right): int
    {
        foreach ($right as $position => $rightValue) {
            if (!array_key_exists($position, $left)) { return 0; }
            $leftValue = $left[$position];
            if ($leftValue === $rightValue) { continue; }
            if ($leftValue === null) { return -1; }
            if ($rightValue === null) { return 1; }
