            $entry + ['sort_values' => array_merge($entry['index_keys'][$index], [$signature])],
            self::FromOrderedSignatures($signatures, $records, $index, $start, $leftLength),
            self::FromOrderedSignatures($signatures, $records, $index, $middle + 1, $length - $leftLength - 1)
