        if ($comparison < 0) { return self::Balance(new self($node->entry, self::Remove($node->left, $values), $node->right)); }
        if ($comparison > 0) { return self::Balance(new self($node->entry, $node->left, self::Remove($node->right, $values))); }
        if ($node->left === null) { return $node->right; }
        if ($node->right === null) { return $node->left; }
        $successor = $node->right;
        while ($successor->left !== null) { $successor = $successor->left; }
