        }
        if ($difference < -1) {
            if (($node->right->right?->height ?? 0) < ($node->right->left?->height ?? 0)) {
                $pivot = $node->right->left;
                $node = new self($node->entry, $node->left, new self($pivot->entry, $pivot->left, new self($node->right->entry, $pivot->right, $node->right->right)));
